messages.content:
1: """Mindcraft island service: graph model, deterministic check-in, crisis guard, public walkers.
2: 
3: Graph shape: root -> MindIsland -> EmotionalEntity -> InteractionEvent
4:                                    EmotionalEntity -> ValueAction
5: """
6: 
7: node MindIsland {
8:     has name: str = "Mind Island";
9: }
10: 
11: node EmotionalEntity {
12:     has label: str = "";
13:     has emotion: str = "";
14:     has intensity: int = 1;
15:     has shape: str = "stone";
16:     has color: str = "#9ca3af";
17:     has placed: bool = False;
18:     has x: int = 0;
19:     has y: int = 0;
20:     has note: str = "";
21: }
22: 
23: node InteractionEvent {
24:     has kind: str = "";
25:     has result: str = "";
26: }
27: 
28: node ValueAction {
29:     has value: str = "";
30:     has action: str = "";
31: }
32: 
33: glob INTERACTIONS: list[str] = ["breathe", "name", "soften", "listen"];
34: 
35: glob CRISIS_TERMS: list[str] = [
36:     "suicide", "suicidal", "kill myself", "end my life", "want to die",
37:     "hurt myself", "self harm", "self-harm", "no reason to live", "better off dead"
38: ];
39: 
40: glob CRISIS_MESSAGE: str = "It sounds like you may be in danger right now. Please reach out for support immediately: call or text 988 (Suicide and Crisis Lifeline, US), call your local emergency number, or contact someone you trust and tell them how you feel. You do not have to go through this alone.";
41: 
42: glob EMOTION_TABLE: list[dict] = [
43:     {"emotion": "anxiety", "label": "Anxious cloud", "shape": "cloud", "color": "#c7d2fe", "keywords": ["anxious", "anxiety", "worried", "worry", "nervous", "stressed", "stress", "overwhelmed"]},
44:     {"emotion": "sadness", "label": "Heavy stone", "shape": "stone", "color": "#93c5fd", "keywords": ["sad", "down", "lonely", "alone", "empty", "grief", "cry", "hopeless"]},
45:     {"emotion": "anger", "label": "Hot ember", "shape": "ember", "color": "#fca5a5", "keywords": ["angry", "anger", "mad", "furious", "annoyed", "frustrated", "irritated"]},
46:     {"emotion": "fear", "label": "Shadow", "shape": "shadow", "color": "#d4d4d8", "keywords": ["afraid", "scared", "fear", "terrified", "panic"]},
47:     {"emotion": "tiredness", "label": "Drifting log", "shape": "log", "color": "#d6c4a8", "keywords": ["tired", "exhausted", "drained", "burnt out", "burned out", "sleepy"]},
48:     {"emotion": "joy", "label": "Bright flower", "shape": "flower", "color": "#fde68a", "keywords": ["happy", "glad", "joy", "excited", "grateful", "calm", "hopeful"]}
49: ];
50: 
51: glob INTERACTION_RESULTS: dict = {
52:     "breathe": "You took three slow breaths with this feeling beside you.",
53:     "name": "You named the feeling out loud. Naming it gives it a shape you can hold.",
54:     "soften": "You let your shoulders drop. The feeling grew a little lighter.",
55:     "listen": "You asked the feeling what it needs and listened without judging."
56: };
57: 
58: """True when the text contains urgent / crisis language."""
59: def is_crisis(text: str) -> bool {
60:     t = text.lower();
61:     for term in CRISIS_TERMS {
62:         if term in t {
63:             return True;
64:         }
65:     }
66:     return False;
67: }
68: 
69: """Deterministic keyword mapping from free text to feeling specs."""
70: def detect_emotions(text: str) -> list[dict] {
71:     t = text.lower();
72:     intensity = 1;
73:     for amp in ["very", "so ", "really", "extremely", "too "] {
74:         if amp in t {
75:             intensity = intensity + 1;
76:         }
77:     }
78:     if intensity > 3 {
79:         intensity = 3;
80:     }
81:     found: list[dict] = [];
82:     for spec in EMOTION_TABLE {
83:         for kw in spec["keywords"] {
84:             if kw in t {
85:                 found.append({
86:                     "emotion": spec["emotion"],
87:                     "label": spec["label"],
88:                     "shape": spec["shape"],
89:                     "color": spec["color"],
90:                     "intensity": intensity
91:                 });
92:                 break;
93:             }
94:         }
95:     }
96:     if len(found) == 0 {
97:         found.append({
98:             "emotion": "unnamed",
99:             "label": "Unnamed pebble",
100:             "shape": "pebble",
101:             "color": "#cbd5e1",
102:             "intensity": intensity
103:         });
104:     }
105:     return found;
106: }
107: 
108: """Plain dict projection of an entity for the client."""
109: def entity_view(e: EmotionalEntity) -> dict {
110:     return {
111:         "id": jid(e),
112:         "label": e.label,
113:         "emotion": e.emotion,
114:         "intensity": e.intensity,
115:         "shape": e.shape,
116:         "color": e.color,
117:         "placed": e.placed,
118:         "x": e.x,
119:         "y": e.y,
120:         "note": e.note
121:     };
122: }
123: 
124: """Get-or-create the island attached to the given root."""
125: def get_island(r: Root) -> MindIsland {
126:     islands = [r -->[?:MindIsland]];
127:     if len(islands) > 0 {
128:         return islands[0];
129:     }
130:     island = MindIsland();
131:     r ++> island;
132:     return island;
133: }
134: 
135: """Resolve an entity id to an EmotionalEntity, or None."""
136: def find_entity(entity_id: str) -> EmotionalEntity | None {
137:     if not entity_id {
138:         return None;
139:     }
140:     found: any = None;
141:     try {
142:         found = jobj(entity_id);
143:     } except Exception {
144:         return None;
145:     }
146:     if isinstance(found, EmotionalEntity) {
147:         return found;
148:     }
149:     return None;
150: }
151: 
152: def clamp(v: int) -> int {
153:     if v < 5 {
154:         return 5;
155:     }
156:     if v > 95 {
157:         return 95;
158:     }
159:     return v;
160: }
161: 
162: walker:pub get_world {
163:     has reports: list[dict] = [];
164: 
165:     can run with Root entry {
166:         island = get_island(here);
167:         entities = [island -->[?:EmotionalEntity]];
168:         report {
169:             "entities": [entity_view(e) for e in entities],
170:             "interactions": INTERACTIONS
171:         };
172:     }
173: }
174: 
175: walker:pub manifest_emotion {
176:     has text: str = "";
177:     has reports: list[dict] = [];
178: 
179:     can run with Root entry {
180:         t = self.text.strip();
181:         if not t {
182:             report {"crisis": False, "error": "Describe how you feel first.", "message": "", "entities": []};
183:             disengage;
184:         }
185:         if is_crisis(t) {
186:             report {"crisis": True, "message": CRISIS_MESSAGE, "entities": []};
187:             disengage;
188:         }
189:         island = get_island(here);
190:         created: list[dict] = [];
191:         for spec in detect_emotions(t) {
192:             e = EmotionalEntity(
193:                 label=spec["label"],
194:                 emotion=spec["emotion"],
195:                 intensity=spec["intensity"],
196:                 shape=spec["shape"],
197:                 color=spec["color"],
198:                 note=t
199:             );
200:             island ++> e;
201:             created.append(entity_view(e));
202:         }
203:         report {"crisis": False, "message": "", "entities": created};
204:     }
205: }
206: 
207: walker:pub place_entity {
208:     has entity_id: str = "";
209:     has x: int = 0;
210:     has y: int = 0;
211:     has reports: list[dict] = [];
212: 
213:     can run with Root entry {
214:         e = find_entity(self.entity_id);
215:         if e is None {
216:             report {"error": "Feeling not found."};
217:             disengage;
218:         }
219:         e.placed = True;
220:         e.x = clamp(self.x);
221:         e.y = clamp(self.y);
222:         report {"entity": entity_view(e)};
223:     }
224: }
225: 
226: walker:pub apply_interaction {
227:     has entity_id: str = "";
228:     has kind: str = "";
229:     has reports: list[dict] = [];
230: 
231:     can run with Root entry {
232:         e = find_entity(self.entity_id);
233:         if e is None {
234:             report {"error": "Feeling not found."};
235:             disengage;
236:         }
237:         if not e.placed {
238:             report {"error": "Place the feeling on the island first."};
239:             disengage;
240:         }
241:         if self.kind not in INTERACTIONS {
242:             report {"error": "Unknown interaction."};
243:             disengage;
244:         }
245:         if self.kind == "soften" and e.intensity > 1 {
246:             e.intensity = e.intensity - 1;
247:         }
248:         result = INTERACTION_RESULTS[self.kind];
249:         ev = InteractionEvent(kind=self.kind, result=result);
250:         e ++> ev;
251:         report {"entity": entity_view(e), "event": {"kind": ev.kind, "result": ev.result}};
252:     }
253: }
254: 
255: walker:pub commit_value_action {
256:     has entity_id: str = "";
257:     has value: str = "";
258:     has action: str = "";
259:     has reports: list[dict] = [];
260: 
261:     can run with Root entry {
262:         e = find_entity(self.entity_id);
263:         if e is None {
264:             report {"error": "Feeling not found."};
265:             disengage;
266:         }
267:         if not e.placed {
268:             report {"error": "Place the feeling on the island first."};
269:             disengage;
270:         }
271:         v = self.value.strip();
272:         a = self.action.strip();
273:         if not v or not a {
274:             report {"error": "Add both what matters to you and one concrete next action."};
275:             disengage;
276:         }
277:         va = ValueAction(value=v, action=a);
278:         e ++> va;
279:         report {"entity": entity_view(e), "action": {"value": va.value, "action": va.action}};
280:     }
281: }
282: 
283: walker:pub get_act_path {
284:     has entity_id: str = "";
285:     has reports: list[dict] = [];
286: 
287:     can run with Root entry {
288:         e = find_entity(self.entity_id);
289:         if e is None {
290:             report {"error": "Feeling not found."};
291:             disengage;
292:         }
293:         events = [e -->[?:InteractionEvent]];
294:         actions = [e -->[?:ValueAction]];
295:         report {
296:             "entity": entity_view(e),
297:             "events": [{"kind": ev.kind, "result": ev.result} for ev in events],
298:             "actions": [{"value": va.value, "action": va.action} for va in actions]
299:         };
300:     }
301: }
302: 
303: walker:pub reset_demo {
304:     has reports: list[dict] = [];
305: 
306:     can run with Root entry {
307:         island = get_island(here);
308:         entities = [island -->[?:EmotionalEntity]];
309:         cleared = len(entities);
310:         for e in entities {
311:             for ev in [e -->[?:InteractionEvent]] {
312:                 del ev;
313:             }
314:             for va in [e -->[?:ValueAction]] {
315:                 del va;
316:             }
317:             del e;
318:         }
319:         report {"cleared": cleared};
320:     }
321: }
